#include <stdio.h>
int main(void){int n,at[100],bt[100],rem[100],wt[100],tat[100],i,t=0,q,done=0;float aw=0,avg=0;printf("Number of processes: ");scanf("%d",&n);if(n<1||n>100)return 1;for(i=0;i<n;i++){printf("Arrival and burst P%d: ",i+1);scanf("%d%d",&at[i],&bt[i]);rem[i]=bt[i];}printf("Quantum: ");scanf("%d",&q);if(q<1)return 1;while(done<n){int progressed=0;for(i=0;i<n;i++)if(rem[i]>0&&at[i]<=t){int run=rem[i]<q?rem[i]:q;rem[i]-=run;t+=run;progressed=1;if(rem[i]==0){tat[i]=t-at[i];wt[i]=tat[i]-bt[i];done++;}}if(!progressed)t++;}printf("PID\tAT\tBT\tWT\tTAT\n");for(i=0;i<n;i++){aw+=wt[i];avg+=tat[i];printf("P%d\t%d\t%d\t%d\t%d\n",i+1,at[i],bt[i],wt[i],tat[i]);}printf("Avg WT=%.2f Avg TAT=%.2f\n",aw/n,avg/n);}